var builder = WebApplication.CreateBuilder(args);

builder.Services.AddEndpointsApiExplorer();
builder.Services.AddValidation();

var app = builder.Build();

app.MapPost("/orders", ([Validate] CreateOrderRequest request) =>
{
    return TypedResults.Created($"/orders/{request.Id}", request);
})
.WithName("CreateOrder");

app.Run();

public record CreateOrderRequest(
    [property: Required, MaxLength(100)] string ProductName,
    [property: Range(1, int.MaxValue)] int Quantity,
    [property: EmailAddress] string CustomerEmail
);

{
  "type": "https://tools.ietf.org/html/rfc9110#section-15.5.1",
  "title": "One or more validation errors occurred.",
  "status": 400,
  "errors": {
    "ProductName": ["The ProductName field is required.", "The length of 'ProductName' must be 100 characters or fewer."],
    "Quantity": ["The field Quantity must be between 1 and 2147483647."]
  }
}

builder.Services.AddValidatorsFromAssemblyContaining<CreateOrderRequestValidator>();

public class CreateOrderRequestValidator : AbstractValidator<CreateOrderRequest>
{
    public CreateOrderRequestValidator()
    {
        RuleFor(x => x.CustomerEmail)
            .NotEmpty().WithMessage("Email is required")
            .EmailAddress();
    }
}
